#!/usr/bin/env python3
"""Patch validated Reco with an EXPERIMENT-ONLY optical-flow detection hook.

The hook is inert unless OEV_FLOW_BRIDGE_FILE points at JSONL generated by
optical_flow_ball_bridge.py. It appends at most one synthetic class-32 Detection
for the current analysis frame before the existing panorama mapping/tracker
chain. No detector thresholds, tracker gates, panner logic, lookahead, backward
bridging, or rendering code is changed.
"""

from pathlib import Path

PATH = Path("/tmp/video-stitcher/crates/reco-core/src/session/detection_dispatch.rs")
s = PATH.read_text()


def replace_once(label: str, old: str, new: str) -> None:
    global s
    count = s.count(old)
    if count != 1:
        raise SystemExit(f"{label}: expected exactly one match, found {count}")
    s = s.replace(old, new, 1)


replace_once(
    "imports",
    """use crate::source::StereoFrame;\n\nimpl StitchSession {\n""",
    """use crate::source::StereoFrame;\n\n// OEV EXPERIMENT ONLY: optional precomputed causal optical-flow continuation.\n// Empty/inert unless OEV_FLOW_BRIDGE_FILE is present in this reco process.\nfn oev_flow_bridge_detection(frame_index: u64) -> Option<Detection> {\n    use std::collections::HashMap;\n    use std::sync::OnceLock;\n\n    static ENTRIES: OnceLock<HashMap<u64, Detection>> = OnceLock::new();\n    let entries = ENTRIES.get_or_init(|| {\n        let Ok(path) = std::env::var(\"OEV_FLOW_BRIDGE_FILE\") else {\n            return HashMap::new();\n        };\n        let Ok(text) = std::fs::read_to_string(&path) else {\n            log::warn!(\"OEV flow bridge: could not read {}\", path);\n            return HashMap::new();\n        };\n        let mut map = HashMap::new();\n        for (line_no, line) in text.lines().enumerate() {\n            if line.trim().is_empty() {\n                continue;\n            }\n            let Ok(v) = serde_json::from_str::<serde_json::Value>(line) else {\n                log::warn!(\"OEV flow bridge: invalid JSON line {}\", line_no + 1);\n                continue;\n            };\n            let Some(fi) = v.get(\"frame_index\").and_then(|x| x.as_u64()) else {\n                continue;\n            };\n            let Some(d) = v.get(\"detection\") else {\n                continue;\n            };\n            let camera = match d.get(\"camera\").and_then(|x| x.as_str()) {\n                Some(\"Left\") => crate::detect::detector::CameraId::Left,\n                Some(\"Right\") => crate::detect::detector::CameraId::Right,\n                _ => continue,\n            };\n            let f = |name: &str| d.get(name).and_then(|x| x.as_f64()).map(|x| x as f32);\n            let Some(class_id) = d.get(\"class_id\").and_then(|x| x.as_u64()) else {\n                continue;\n            };\n            let (Some(confidence), Some(center_x), Some(center_y), Some(width), Some(height)) = (\n                f(\"confidence\"), f(\"center_x\"), f(\"center_y\"), f(\"width\"), f(\"height\")\n            ) else {\n                continue;\n            };\n            map.insert(fi, Detection {\n                camera,\n                class_id: class_id as u16,\n                confidence,\n                center_x,\n                center_y,\n                width,\n                height,\n            });\n        }\n        log::info!(\"OEV flow bridge: loaded {} synthetic frame continuations from {}\", map.len(), path);\n        map\n    });\n    entries.get(&frame_index).copied()\n}\n\nimpl StitchSession {\n""",
)

replace_once(
    "mutable-detections",
    """            let detections = match frame {\n""",
    """            let mut detections = match frame {\n""",
)

replace_once(
    "inject-before-map",
    """            self.detection.last_detections = self.map_detections(detections);\n        }\n\n        let calibration = self.core.pipeline().calibration();\n""",
    """            if let Some(flow_det) = oev_flow_bridge_detection(analysis_index) {\n                // The generator emits only during frames where the control\n                // selected track was not a genuine YOLO Tracking observation.\n                // Feed the continuation through the ordinary mapping + tracker\n                // gates so it can still be rejected by max-jump/player-anchor.\n                log::debug!(\n                    \"OEV flow bridge: inject frame={} cam={:?} center=({:.4},{:.4}) conf={:.3}\",\n                    analysis_index, flow_det.camera, flow_det.center_x, flow_det.center_y, flow_det.confidence\n                );\n                detections.push(flow_det);\n            }\n            self.detection.last_detections = self.map_detections(detections);\n        }\n\n        let calibration = self.core.pipeline().calibration();\n""",
)

PATH.write_text(s)
print("OEV_OPTICAL_FLOW_BRIDGE_HOOK_APPLIED")
print("  env=OEV_FLOW_BRIDGE_FILE")
print("  injection_point=detect_and_track_only before map_detections")
print("  downstream=existing mapper -> trackers -> backward bridge -> panner")
